assert CharacterOrbitLabel(CharacterOrbitRep("13.f")) eq "13.f";

print "  ConreyConjugates";
assert MinimalConreyConjugate(1,1) eq 1 and MaximalConreyConjugate(1,1) eq 1 and IsConreyConjugate(1,1,1);
for q in [2..30] do
