        assert MinimalConreyConjugate(q,n) eq Min(C);
        assert MaximalConreyConjugate(q,n) eq Max(C);
        assert &and[IsConreyConjugate(q,n,n2) eq (n2 in C) : n2 in U];
    end for;
end for;
