print "  ConreyRoundTripAndInvariants";
// DirichletCharacter(q,n)/CyclotomicConreyCharacter round trip and invariants
// vs Magma built-ins for all Conrey characters of modulus q <= 30
for q in [1..30] do
    for n in [m:m in [1..q]|GCD(m,q) eq 1] do
        chi := DirichletCharacter(q,n);
        assert Modulus(chi) eq q;
        assert ConreyIndex(chi) eq n;                       // round trip
        assert Order(chi) eq CharacterOrder(q,n);
        assert Conductor(chi) eq Conductor(q,n);
        assert Integers()!Evaluate(chi,-1) eq Parity(q,n);  // parity = chi(-1)
        assert Degree(q,n) eq EulerPhi(Order(chi));
        assert IsReal(q,n) eq (Order(chi) le 2);
        assert IsPrimitiveCharacter(q,n) eq (Conductor(chi) eq q);
        assert ConreyLabel(chi) eq Sprintf("%o.%o",q,n);
    end for;
end for;

print "  ConreyCharacterAngles";
// vector vs scalar agreement, Conrey symmetry, total multiplicativity
for q in [2,3,4,5,7,8,9,12,16,24,36,40,48] do
    S := [1..q+5];
    for n in [m:m in [1..q]|GCD(m,q) eq 1] do
        A := ConreyCharacterAngles(q,n,S);
        assert A eq [ConreyCharacterAngle(q,n,m):m in S];
        for m in [m:m in S|GCD(m,q) eq 1] do  // chi_q(n,m) = chi_q(m,n)
            assert ConreyCharacterAngle(q,n,m) eq ConreyCharacterAngle(q,m,n);
        end for;
        for m1 in [2,3,5,7] do for m2 in [3,4,9] do  // chi(m1)chi(m2) = chi(m1*m2)
            if GCD(m1*m2,q) eq 1 then
                assert NormalizedAngle(ConreyCharacterAngle(q,n,m1)+ConreyCharacterAngle(q,n,m2)) eq ConreyCharacterAngle(q,n,m1*m2);
            end if;
        end for; end for;
    end for;
end for;
