            assert ConreyCharacterAngle(q3,n3,m) eq NormalizedAngle(ConreyCharacterAngle(q1,n1,m)+ConreyCharacterAngle(q2,n2,m));
        end for;
    end for; end for;
end for; end for;
assert ConreyCharacterProduct("5.2","3.2") eq "15.2";
q,n := ConreyCharacterProduct(1,1,8,5); assert q eq 8 and n eq 5;

print "  ConductorProduct";
for q1 in [8,12,16,40,75] do for n1 in S1[1..Min(6,#S1)] where S1 := [m:m in [1..q1]|GCD(m,q1) eq 1] do
    for q2 in [8,20,27] do for n2 in S2[1..Min(4,#S2)] where S2 := [m:m in [1..q2]|GCD(m,q2) eq 1] do
        q3,n3 := ConreyCharacterProduct(q1,n1,q2,n2);
        c := ConductorProduct(q1,n1,q2,n2);
        assert c eq Conductor(q3,n3);
        assert IsDivisibleBy(c,ConductorProductBound(Conductor(q1,n1),Conductor(q2,n2)));
    end for; end for;
end for; end for;
assert ConductorProduct("8.3","8.3") eq 1;

print "  PrimitiveConductorProduct";
for q1 in [5,8,13,16,25] do
    P1 := [n:n in [1..q1]|GCD(n,q1) eq 1 and Conductor(q1,n) eq q1];
    for q2 in [8,9,16,40] do
        P2 := [n:n in [1..q2]|GCD(n,q2) eq 1 and Conductor(q2,n) eq q2];
        for n1 in P1[1..Min(3,#P1)] do for n2 in P2[1..Min(3,#P2)] do
            assert PrimitiveConductorProduct(q1,n1,q2,n2) eq ConductorProduct(q1,n1,q2,n2);
            assert PrimitiveConductorProduct(Sprintf("%o.%o",q1,n1),Sprintf("%o.%o",q2,n2)) eq ConductorProduct(q1,n1,q2,n2);
        end for; end for;
    end for;
end for;

print "  Twist";
for t in [<11,3,8,5>,<5,2,3,2>,<8,3,5,2>,<9,2,4,3>,<7,3,7,3>] do
    q1 := t[1]; n1 := t[2]; q2 := t[3]; n2 := t[4];
    q,n := Twist(q1,n1,q2,n2);
    assert Twist(Sprintf("%o.%o",q1,n1),Sprintf("%o.%o",q2,n2)) eq Sprintf("%o.%o",q,n);
    q3,n3 := ConreyCharacterProduct(q1,n1,q2,n2);
    assert q eq LCM(q1,Conductor(q2,n2)*Conductor(q3,n3));  // modulus per docstring
    q4,n4 := ConreyCharacterProduct(q3,n3,q2,n2);           // tchi = chi*psi^2
    for m in [m:m in [2..20]|GCD(m,q*q4) eq 1] do
        assert ConreyCharacterAngle(q,n,m) eq ConreyCharacterAngle(q4,n4,m);
    end for;
    tchi := Twist(DirichletCharacter(q1,n1),DirichletCharacter(q2,n2));
    assert Modulus(tchi) eq q and ConreyIndex(tchi) eq n;
end for;

print "  SquareRoots";
// full-group brute force: SquareRoots(chi) = {psi : psi^2 = chi}
for N in [5,7,8,9,12,13,15,16] do
    G := FullDirichletGroup(N);
    for chi in Elements(G) do
        S := SquareRoots(chi);
        assert #Set(S) eq #S;
        for psi in S do assert psi^2 eq chi; end for;
        assert Set(S) eq {psi:psi in Elements(G)|psi^2 eq chi};
    end for;
end for;
G := DirichletGroup(12);  // trivial character in the rational group
assert Set(SquareRoots(G!1)) eq {psi:psi in Elements(G)|psi^2 eq G!1};

print "  DirichletCharacterFromAngles";
// non-standard generators: 6=2^5 generates (Z/13)*, [7,3] generates (Z/16)*
chi := DirichletCharacter(13,4);
psi := DirichletCharacterFromAngles(13,[6],ConreyCharacterAngles(13,4,[6]));
assert &and[psi(m) eq chi(m):m in [1..13]];
chi := DirichletCharacter(16,3);
psi := DirichletCharacterFromAngles(16,[7,3],ConreyCharacterAngles(16,3,[7,3]));
assert &and[psi(m) eq chi(m):m in [1..16]];
for t in [<13,4>,<16,3>,<40,7>] do  // 2-argument version, standard generators
    chi := DirichletCharacter(t[1],t[2]);
    psi := DirichletCharacterFromAngles(t[1],ConreyCharacterAngles(t[1],t[2]));
    assert &and[psi(m) eq chi(m):m in [1..t[1]]];
end for;
U := UnitGenerators(16);
v := TranslatedCharacterAngles(16,[7,3],ConreyCharacterAngles(16,3,[7,3]),U);
assert v eq ConreyCharacterAngles(16,3,U);

print "  CharacterFromValues";
for t in [<13,4>,<15,4>,<16,3>,<7,1>] do
    N := t[1];
    chi := DirichletCharacter(N,t[2]);
    U := UnitGenerators(N);
    xi, o := CharacterFromValues(N,U,[Codomain(chi)|chi(u):u in U]:Orbit:=true);
    assert &and[xi(m) eq chi(m):m in [0..N+3]];
    assert o eq CharacterOrbitIndex(chi);
end for;

print "  MapVersionsOfInvariants";
for t in [<13,4>,<13,1>,<16,3>,<16,15>,<15,14>,<11,2>] do
    N := t[1];
    chi := DirichletCharacter(N,t[2]);
    U := UnitGenerators(N);
    xi := CharacterFromValues(N,U,[Codomain(chi)|chi(u):u in U]);
    assert CharacterOrder(xi,N) eq Order(chi);
    if not (Order(chi) eq 2 and Codomain(chi) eq Rationals()) then
        // excluded case hits known bug: Degree(xi,N) returns 2 for quadratic
        // characters with rational codomain (should be 1)
        assert Degree(xi,N) eq EulerPhi(Order(chi));
    end if;
    assert Parity(xi) eq Integers()!Evaluate(chi,-1);
    assert IsReal(xi,N) eq (Order(chi) le 2);
    // note: conductors here are 1, prime, prime power, or = N; the known
    // Conductor(xi,N) bug (imprimitive character of composite modulus with
    // omitted prime) is excluded until fixed
    assert Conductor(xi,N) eq Conductor(chi);
end for;

print "  ComplexAndRealConreyValues";
CC := ComplexField(50); RR := RealField(50);
rpi := Pi(RR);
for t in [<7,3>,<16,3>,<40,7>] do
    q := t[1]; n := t[2];
    xi := ComplexConreyCharacter(q,n,CC);
    for m in [1..2*q] do
        if GCD(m,q) eq 1 then
            a := ConreyCharacterAngle(q,n,m);
            assert Abs(xi(m)-Exp(2*Pi(CC)*CC.1*a)) lt 10.0^-30;
            assert Abs(ConreyCharacterRealValue(q,n,m,RR)-Cos(2*rpi*a)) lt 10.0^-30;
            assert Abs(ConreyCharacterComplexValue(q,n,m,CC)-xi(m)) lt 10.0^-30;
        else
            assert xi(m) eq 0;
            assert ConreyCharacterComplexValue(q,n,m,CC) eq 0;
            assert ConreyCharacterRealValue(q,n,m,RR) eq 0;
        end if;
    end for;
    xi2 := ComplexConreyCharacter(Sprintf("%o.%o",q,n),CC);
    assert Abs(xi2(3)-xi(3)) lt 10.0^-30;
    S := [m:m in [1..q]|GCD(m,q) eq 1];  // coprime only: values at non-coprime m hit known bug
    V := ConreyCharacterComplexValues(q,n,S,CC);
    assert &and[Abs(V[i]-xi(S[i])) lt 10.0^-30:i in [1..#S]];
end for;

print "  ConreyConjugatesEmbedded";
chi := DirichletCharacter("13.2");
K := Codomain(chi);
xi := map<Integers()->K|x:->chi(x)>;
L := ConreyConjugates(chi,xi);
assert #L eq Degree(K) and Set(L) eq {2,6,7,11};
CC := ComplexField(30);
for m in [2,5,6] do  // j-th embedding of xi is the Conrey character L[j]
    C := Conjugates(xi(m):Precision:=30);
    for j in [1..#L] do
        assert Abs(C[j]-Exp(2*Pi(CC)*CC.1*ConreyCharacterAngle(13,L[j],m))) lt 10.0^-20;
    end for;
end for;

